/**
 * GitHub-compatible heading slugifier so authored `#section` anchor links in
 * Phase 1 Markdown documents match the `id` attributes generated by VitePress.
 */
export function githubSlugify(text: string): string {
  return text
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s-]/gu, '')
    .replace(/\s/g, '-');
}
